 Instrumentation inst=(Instrumentation)Proxy.newProxyInstance(Check.class.getClassLoader(),new Class[]{Instrumentation.class},(proxy,method,params)->{if(method.getName().equals("addTransformer")){ClassFileTransformer t=(ClassFileTransformer)params[0];for(String n:new String[]{"org/opentaint/dataflow/bidi/store/DemandStore","org/opentaint/dataflow/bidi/ap/LimitKt","org/opentaint/dataflow/bidi/engine/BlockRunState"}){Path p=Path.of(args[0],n+".class");byte[] out=t.transform(Check.class.getClassLoader(),n,null,null,Files.readAllBytes(p));System.out.println(n+" => "+(out==null?"FAILED":out.length));}}return null;});
